from typing import Union
from dataclasses import dataclass

from taf.ue.fastmile.exceptions import InvalidFormatOptionException


@dataclass
class TputFormat:
    option: str
    multiplier: float
    unit: str


class TputFormats:
    options: tuple[TputFormat, ...] = (
        TputFormat('b', 1000, 'Bits'),
        TputFormat('k', 1, 'kBits'),
        TputFormat('m', 0.001, 'MBits'),
        TputFormat('g', 0.000001, 'GBits'),
    )
    default: TputFormat = TputFormat('k', 1, 'kBits')

    @staticmethod
    def valid_option(option: str) -> bool:
        """Return if given option is supported."""
        if not isinstance(option, str):
            return False
        option = option.lower()
        return option in TputFormats.available_options()

    @staticmethod
    def available_options() -> list[str]:
        """Return available formatting options."""
        return [x.option for x in TputFormats.options]

    @staticmethod
    def get_tput_format(option: str) -> TputFormat:
        """Return TputFormat option based on given option."""
        option = option.lower()
        for tput_format in TputFormats.options:
            if tput_format.option == option:
                return tput_format
        raise InvalidFormatOptionException(option)

    @staticmethod
    def get_default_format() -> TputFormat:
        """Return default format."""
        return TputFormats.default

    @staticmethod
    def get_multiplier(option: str) -> float:
        """Return multiplier related to given option."""
        if TputFormats.valid_option(option):
            return TputFormats.get_tput_format(option).multiplier
        raise InvalidFormatOptionException(option)

    @staticmethod
    def get_default_multiplier() -> float:
        """Return default multiplier."""
        return TputFormats.default.multiplier

    @staticmethod
    def change_unit(option: str, value: Union[int, float, list, tuple]) -> Union[int, float, list, tuple]:
        """Change unit based on option."""
        if not isinstance(value, (list, tuple)) and not isinstance(value, (int, float)):
            raise TypeError(f"Invalid type for multiplier {type(value)}.")

        if TputFormats.valid_option(option):
            factor = TputFormats.get_multiplier(option)
        else:
            factor = TputFormats.get_default_multiplier()
        if isinstance(value, (list, tuple)):
            return type(value)(x * factor for x in value)
        else:
            return value * factor
